package store

import "errors"

var ErrNotFound = errors.New("not found")

type Schedule struct {
	ID      string  `json:"id"`
	OwnerID string  `json:"ownerId"`
	Title   string  `json:"title"`
	Entries []Entry `json:"entries"`
}

type Entry struct {
	Start string `json:"start"`
	End   string `json:"end"`
	Label string `json:"label"`
}

// KV is a durable key-value table (SQLite-backed in production, in-memory in tests).
type KV interface {
	Put(ns, key, value string) error
	Get(ns, key string) (string, error) // ErrNotFound when missing
}

type Store struct {
	KV        KV
	Schedules interface {
		Get(id string) (Schedule, error) // ErrNotFound when missing
	}
}

