package auth

import (
	"net/http"

	"example.com/api/internal/app"
)

// Require wraps a handler so anonymous callers get 401.
func Require(h app.Handler) app.Handler {
	return func(c app.Ctx) error {
		if c.UserID() == "" {
			return c.NoContent(http.StatusUnauthorized)
		}
		return h(c)
	}
}

