package http

import (
	stdhttp "net/http"
	"strings"

	"example.com/api/internal/app"
)

// Router maps method+path to handlers. Paths use :name params.
// A known path with an unrouted method returns 405; an unknown path returns 404; a handler that
// returns an error gets 500.
type Router struct {
	routes map[string]map[string]app.Handler
	newCtx func(w stdhttp.ResponseWriter, r *stdhttp.Request, params map[string]string) app.Ctx
}

func NewRouter(newCtx func(stdhttp.ResponseWriter, *stdhttp.Request, map[string]string) app.Ctx) *Router {
	return &Router{routes: map[string]map[string]app.Handler{}, newCtx: newCtx}
}

func (r *Router) GET(path string, h app.Handler)  { r.add("GET", path, h) }
func (r *Router) POST(path string, h app.Handler) { r.add("POST", path, h) }

func (r *Router) add(method, path string, h app.Handler) {
	if r.routes[path] == nil {
		r.routes[path] = map[string]app.Handler{}
	}
	r.routes[path][method] = h
}

func (r *Router) ServeHTTP(w stdhttp.ResponseWriter, req *stdhttp.Request) {
	for pattern, byMethod := range r.routes {
		params, ok := match(pattern, req.URL.Path)
		if !ok {
			continue
		}
		h, ok := byMethod[req.Method]
		if !ok {
			w.WriteHeader(stdhttp.StatusMethodNotAllowed)
			return
		}
		if err := h(r.newCtx(w, req, params)); err != nil {
			w.WriteHeader(stdhttp.StatusInternalServerError) // a handler error is a 500, never an empty 200
		}
		return
	}
	w.WriteHeader(stdhttp.StatusNotFound)
}

func match(pattern, path string) (map[string]string, bool) {
	ps, xs := strings.Split(strings.Trim(pattern, "/"), "/"), strings.Split(strings.Trim(path, "/"), "/")
	if len(ps) != len(xs) {
		return nil, false
	}
	params := map[string]string{}
	for i, p := range ps {
		if strings.HasPrefix(p, ":") {
			params[p[1:]] = xs[i]
		} else if p != xs[i] {
			return nil, false
		}
	}
	return params, true
}

