package schedules

import (
	"net/http"

	"example.com/api/internal/app"
	"example.com/api/internal/auth"
	"example.com/api/internal/store"
)

type router interface{ GET(string, app.Handler); POST(string, app.Handler) }

func Register(r router) {
	r.GET("/schedules/:id", auth.Require(get))
}

// PublicView is a schedule without private fields (no owner id), safe to show to anyone.
func PublicView(s store.Schedule) map[string]any {
	return map[string]any{"id": s.ID, "title": s.Title, "entries": s.Entries}
}

func get(c app.Ctx) error {
	s, err := c.Store().Schedules.Get(c.Param("id"))
	if err != nil {
		return c.NoContent(http.StatusNotFound)
	}
	if s.OwnerID != c.UserID() {
		return c.NoContent(http.StatusForbidden)
	}
	return c.JSON(http.StatusOK, s)
}

