package testutil

import (
	"net/http/httptest"
	"testing"

	"example.com/api/internal/app"
	"example.com/api/internal/store"
)

// Server runs a real router over an in-memory store with fixtures: schedule s1 owned by u1, s2
// owned by u2. Config.WebOrigin is https://app.test.
type Server struct {
	Store *store.Store
	h     *httptest.Server
}

type router interface {
	GET(string, app.Handler)
	POST(string, app.Handler)
}

// NewServer builds the router, calls register on it (e.g. http.Register or share.Register) and serves it.
func NewServer(t *testing.T, register any) *Server { return newServer(t, register) }

// AsUser and Anonymous return a client; GET/POST return a Response with ExpectStatus(t, code)
// and JSON(t, &v). KV(ns, key) reads the store directly for assertions.
func (s *Server) AsUser(id string) *Client { return &Client{s: s, user: id} }
func (s *Server) Anonymous() *Client     { return &Client{s: s} }

type Client struct {
	s    *Server
	user string
}

