import { useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import type { Schedule } from '@app/contract'
import { apiGet } from '../api/client'
import { useCurrentUserId } from '../session'

export function SchedulePage() {
  const { id } = useParams()
  const userId = useCurrentUserId()
  const [schedule, setSchedule] = useState<Schedule | null>(null)
  useEffect(() => { apiGet<Schedule>(`/schedules/${id}`).then(setSchedule) }, [id])
  if (!schedule) return <p>Loading…</p>
  const isOwner = userId !== null && userId === schedule.ownerId
  return (
    <main>
      <h1>{schedule.title}</h1>
      <div className="actions">{isOwner && null /* owner actions go here */}</div>
      <ul>{schedule.entries.map(e => <li key={e.start}>{e.label}</li>)}</ul>
    </main>
  )
}

